using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "EnhanceCustomTag", menuName = "Data/Battle/Battle Actions/EnhanceCustomTag", order = 0)]
public class EnhanceCustomTag : Tag
{
	[SerializeField]
	private EnhanceAction enhanceAction;

	[SerializeField]
	private bool playFeedback;

	public override string GetTagDescription()
	{
		return string.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(base.TagIDDescription), enhanceAction.FinalValueForTag(playFeedback) + enhanceAction.GetResearchModifierText());
	}
}
